UPDATE borrow_record
SET status      = 1,
    return_time = #{returnTime},
    fine_amount = #{fineAmount}
WHERE id = #{id}
  AND status = 0

mapper.select:
SELECT br.id, br.user_id, br.book_id, br.borrow_time, br.due_date, br.return_time, br.status, u.user_name, b.name AS book_name FROM borrow_record br LEFT JOIN user u ON br.user_id = u.id LEFT JOIN book b ON br.book_id = b.id
AND br.user_id = #{userId}
AND br.book_id = #{bookId}
AND br.status = #{status}
AND b.name LIKE concat('%',#{bookName},'%')
AND u.user_name LIKE concat('%',#{userName},'%')
AND br.borrow_time BETWEEN #{startTime} AND #{endTime}
ORDER BY br.id DESC
LIMIT #{offset},#{size}

